  if(kind==='odometer')return [['observed_on','Date',{type:'date'}],['miles','Odometer · miles',{type:'number',step:'0.1'}]];
  if(kind==='oil_analysis')return [['analysis_status','Sample status',{options:[['awaiting_mailing','Awaiting mailing'],['submitted','Submitted to lab'],['reported','Report received']]}],['lab','Lab'],['sample_date','Sample date',{type:'date'}],['report_date','Report date',{type:'date'}],['report_number','Report number'],['order_number','Order number'],['unit_id','Lab unit ID'],['engine','Engine'],['oil_type','Oil type'],['comparison_miles','Comparison miles',{type:'number',step:'0.1'}],['makeup_quarts','Make-up oil · quarts',{type:'number',step:'0.01'}],['odometer','Odometer · miles',{type:'number',step:'0.1'}],['oil_miles','Miles on oil',{type:'number',step:'0.1'}],['collection_notes','Collection notes',{type:'textarea',wide:true}],['lab_comments','Lab comments',{type:'textarea',wide:true}]];
  if(['receipt','service'].includes(kind))return [['occurred_on','Date',{type:'date'}],['date_precision','Date precision',{options:[['day','Exact day'],['month','Month only'],['year','Year only'],['unknown','Unknown']]}],['odometer','Odometer · miles',{type:'number',step:'0.1'}],['cost','Cost · USD',{type:'number',step:'0.01'}],['vendor','Vendor or shop'],['odometer_approximate','Odometer accuracy',{options:[['0','Exact'],['1','Approximate']]}]];
  return [];
