function captureInitial(record) {const payload=record?.payload||{};return {id:record?.id,kind:record?.kind||local().captureInitial?.kind||'receipt',vehicle_id:record?.vehicle_id||local().captureInitial?.vehicle_id||'',title:record?.title||'',notes:record?.notes||'',...Object.fromEntries(Object.entries(payload).filter(([k])=>!['measurements','parts'].includes(k)).map(([k,v])=>['payload_'+k,k==='filled_at'&&v?(String(v).length===10?String(v)+'T00:00':String(v).replace(' ','T').slice(0,16)):typeof v==='boolean'?(v?'1':'0'):v])),parts:list(payload.parts).map(row=>typeof row==='string'?{name:row}:{...row}),measurements:list(payload.measurements).map(row=>({...row})),payload_full_tank:payload.full_tank===false||payload.full_tank===0?'0':'1',payload_missed_fill:payload.missed_fill?'1':'0',payload_analysis_status:payload.analysis_status||'awaiting_mailing'};}
